/* ==UserStyle==
@name status.cafe Catppuccin
@namespace github.com/catppuccin/userstyles/styles/status.cafe
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/status.cafe
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/status.cafe/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Astatus.cafe
@description Soothing pastel theme for status.cafe
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document regexp("https://status\\.cafe/(?!users).*"),
  domain("forum.status.cafe") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    background-color: @base;

    body {
      background-color: @base;
      color: @text;
    }

    textarea {
      background-color: @mantle;
      color: @text;
      border-color: @surface1;
      border-style: solid;
      border-width: 1px;
      border-radius: 2px;
      padding: 3px;
    }

    input {
      background-color: @mantle;
      color: @text;
      border-color: @surface1;
      border-style: solid;
      border-width: 1px;
      border-radius: 4px;
      padding: 2px 5px;
      :hover {
        background-color: darken(@mantle, 2%);
      }

      :active {
        background-color: @crust;
        border-color: @surface0;
      }
    }

    textarea:hover,
    input:hover {
      border-color: darken(@surface1, 5%);
    }

    .flash {
      background-color: @green;
    }

    a:not(.flash a) {
      color: @accent;
    }

    a:visited:not(.flash a) {
      color: darken(@accent, 5%);
    }

    table,
    th,
    td {
      border-color: @surface1 !important;
    }

    thead {
      background-color: @surface1;
      color: @text;
    }

    .forum {
      background-color: @yellow;
      a {
        color: darken(@blue, 10%) !important;
      }
    }

    tbody,
    .topic > tbody > tr:nth-child(2n) {
      background-color: @mantle;
    }

    hr {
      background-color: @surface1;
    }

    .signature {
      border-top-color: @surface0;
    }

    & when (@flavor = latte) {
      a:visited:not(.flash a) {
        color: darken(@accent, 10%);
      }
      input:active {
        background-color: @surface0;
        border-color: @surface2;
      }
    }
  }
}

